using Microsoft.Dynamics.HR.Platform.Instrumentation;

public class NVLeavePlanAdditionalTier extends common
{
}

Method.Source:
/// <summary>
///    Finds the specified record in the <c>NVLeavePlanAdditionalTier</c> table.
/// </summary>
/// <param name="_recId">
///    The record ID of the record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that specifies whether to read the record for update; optional.
/// </param>
/// <param name="_concurrencyModel">
///    An enumeration value that indicates the concurrency setting to use on the table; optional.
/// </param>
/// <returns>
///    A record in the <c>NVLeavePlanAdditionalTier</c> table; otherwise, an empty record.
/// </returns>
[Hookable(False)]
public static NVLeavePlanAdditionalTier find(
    RefRecId _recId,
    boolean _forUpdate = false,
    ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
{
    NVLeavePlanAdditionalTier leavePlanAdditionalTier;

    leavePlanAdditionalTier.selectForUpdate(_forUpdate);
    if (_forUpdate && _concurrencyModel != ConcurrencyModel::Auto)
    {
        leavePlanAdditionalTier.concurrencyModel(_concurrencyModel);
    }

    select firstonly leavePlanAdditionalTier
        where leavePlanAdditionalTier.RecId == _recId;

    return leavePlanAdditionalTier;
}

public boolean validateField(FieldId _fieldIdToCheck)
{
    boolean ret = super(_fieldIdToCheck);

    switch (_fieldIdToCheck)
    {
        case fieldNum(LeavePlanTier, QualifyingAmount):
            ret = ret && this.validateUniqueQualifyingAmount();
            break;
    }

    return ret;
}

public boolean validateWrite()
{
    boolean ret = super();

    ret = ret
        && this.validateUniqueQualifyingAmount();

    return ret;
}

private boolean validateUniqueQualifyingAmount()
{
    boolean isValid = true;

    NVLeavePlanAdditionalTier planAdditionalTier;

    select firstonly RecId from planAdditionalTier
        where planAdditionalTier.RecId  != this.RecId
        && planAdditionalTier.PlanTier  == this.PlanTier
        && planAdditionalTier.Type      == this.Type
        && planAdditionalTier.QualifyingAmount == this.QualifyingAmount;

    if (planAdditionalTier)
    {
        switch (planAdditionalTier.Category)
        {
            case NVLeaveCategory::MOS:
                isValid = checkFailed(strFmt(
                    "@Leave:LeavePlanTier_SameMonthsOfService",
                    this.QualifyingAmount,
                    LeavePlan::find(LeavePlanTier::find(this.PlanTier).Plan).Name));
                break;
        }
    }

    return isValid;
}

public void insert()
{
    if (!this.AdditionalTierNumber)
    {
        this.fillAdditionalTierNumber();
    }

    super();
}

[Hookable(False)]
private static LineNum getLastAdditionalTierNumber(RecId _planTierRecId, LeaveTypeRecId _typeRecId)
{
    NVLeavePlanAdditionalTier planAdditionalTier;

    select maxof(AdditionalTierNumber) from planAdditionalTier
        where planAdditionalTier.Type       == _typeRecId
            && planAdditionalTier.PlanTier  == _planTierRecId;

    return planAdditionalTier.AdditionalTierNumber;
}
